using CB701_KleberCustAddressIntegrationHelper;

/// <summary>
/// Kleber validate customer address
/// The class <c>METKleberValidateCustAddressHelper</c> contains logic to validate customer Address.
/// </summary>
class METKleberValidateCustAddressHelper
{
    CustTable                   custTable;
    AddressCountryRegionId      countryRegionId;
    TransDate                   todayDate;
    FormDataSource              callerDataSource;
    FormDataSource              dirPartyPostalAddressView_ds;

}

Method.Source:
/// <summary>
/// Acts as an entry point when this class is invoked from form.
/// </summary>
/// <param name = "_args"> <c>Arg</c>. </param>
public static void main(Args _args)
{
    FormRun formRun = _args.caller();

    if (formRun && formRun.name() == formStr(LogisticsPostalAddressGrid))
    {
        METCustParameters custParameters = METCustParameters::Find();

        if (custParameters.KleberValidationServiceAPIMSecretKeyVaultRef == 0
            || custParameters.KleberPredictiveServiceAPIMURL == '' || custParameters.TenantIdKeyVaultRef == 0)
        {
            return;
        }

        FormDataSource dirPartyPostalAddressView_ds = formRun.dataSource(formDataSourceStr(LogisticsPostalAddressGrid, DirPartyPostalAddressView)) as FormDataSource;
        DirPartyPostalAddressView callerDirPartyPostalAddressView = dirPartyPostalAddressView_ds.cursor() as DirPartyPostalAddressView;
        // Save off the data source position since the save and dialog operations move the position
        int position = dirPartyPostalAddressView_ds.getPosition();

        KeyVaultParameters keyVaultParameter = KeyVaultParameters::findRecId(KeyVaultCertificateTable::findRecId(custParameters.KleberValidationServiceAPIMSecretKeyVaultRef).KeyVaultRef);

        if (!keyVaultParameter)
        {   
            throw error("@MET:KleberAddressValidationAPIMKeyVaultParameterNotFound");
        }

        try
        {         
            str oauthToken = METTokenGenerator::generateOAuthToken(keyVaultParameter.AppClientId, keyVaultParameter.getClientSecretKey(), custParameters.getTenantIdSecret());

            if (strLen(oauthToken) < 0)
            {
                throw error("@MET:KleberOAuthTokenNotGenerated");
            }

            METKleberCustAddressSearchAndvalidationHelper custAddressSearchAndvalidationHelper = new METKleberCustAddressSearchAndvalidationHelper();
            METKleberValidateCustAddressRequestContract validateCustAddressRequestContract = new METKleberValidateCustAddressRequestContract();
            int requestId = RandomGenerate::construct().randomInt(10000, 5000000);
            validateCustAddressRequestContract.parmAddressLine1(callerDirPartyPostalAddressView.Street);
            validateCustAddressRequestContract.parmDepartmentCode(custParameters.KleberDepartmentCode);
            validateCustAddressRequestContract.parmLocality(callerDirPartyPostalAddressView.City);
            validateCustAddressRequestContract.parmPostcode(callerDirPartyPostalAddressView.ZipCode);
            validateCustAddressRequestContract.parmState(callerDirPartyPostalAddressView.State);
            validateCustAddressRequestContract.parmRequestId(int2Str(requestId));

            str validateAddressJson = FormJsonSerializer::serializeClass(validateCustAddressRequestContract);

            str jsonRespone = custAddressSearchAndvalidationHelper.PerformPostRequestSync(oauthToken, custParameters.KleberValidationServiceAPIMURL,
                                                                                          custParameters.getKleberAddressValidationServiceApimKeySecret(),
                                                                                          validateAddressJson, true);

            METKleberValidateCustAddressResponseContract validationResponse = FormJsonSerializer::deserializeObject(className2Id(classStr(METKleberValidateCustAddressResponseContract)), jsonRespone);

            switch(validationResponse.parmErrorType())
            {
                case strUpr("@SYS1369"):
                case strLwr("@SYS1369"):
                    METKleberValidateCustAddressHelper::updateAddressVerificationStatus(position, callerDirPartyPostalAddressView.Location, dirPartyPostalAddressView_ds, validationResponse.parmValidAddress());
                    break;

                case strUpr("@SYS6998"):
                case strLwr("@SYS6998"):
                    warning(validationResponse.parmErrorMessage());
                    break;

                case strUpr("@SYS8500"):
                case strLwr("@SYS8500"):
                    throw Error(validationResponse.parmErrorMessage());

                default:
                    Info("@MET:NoKleberErrorMessage");
                    break;

            }
        }
        catch (Exception::CLRError)
        {
            System.Exception ex = ClrInterop::getLastException();
            if (ex != null)
            {
                ex = ex.get_InnerException();
                if (ex != null)
                {
                    error(ex.ToString());
                }
            }
        }
    }
    else
    {
        throw error(Error::wrongUseOfFunction(funcName()));
    }
}

/// <summary>
/// Update address verification status
/// </summary>
/// <param name = "_postition">Record position</param>
/// <param name = "_location">Location recId</param>
/// <param name = "_dirPartyPostalAddressView_ds">DirPartyPostalAddressView datasource</param>
/// <param name = "_isValidAddress">Response return field value</param>
public static void updateAddressVerificationStatus(int _postition, LogisticsLocationRecId _location, FormDataSource _dirPartyPostalAddressView_ds, str _isValidAddress)
{
    ttsbegin;
    LogisticsPostalAddress logisticsPostalAddress = LogisticsPostalAddress::findByLocation(_location, true);
    if (str2enum(NoYes::Yes, _isValidAddress) == NoYes::Yes)
    {
        logisticsPostalAddress.METVerified = NoYes::Yes;
    }
    else
    {
        logisticsPostalAddress.METVerified = NoYes::No;
    }
    logisticsPostalAddress.validTimeStateUpdateMode(ValidTimeStateUpdate::Correction);
    logisticsPostalAddress.update();
    ttscommit;

    _dirPartyPostalAddressView_ds.research();

    _dirPartyPostalAddressView_ds.setPosition(_postition);

    info("@MET:KleberValidateCustomerAddress");
}
